// pages/index.js
import { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';  // ここでsupabaseをインポート

export default function Home() {
  const [data, setData] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const { data, error } = await supabase
        .from('your_table')  // 適切なテーブル名に変更
        .select('*');

      if (error) {
        console.error('Error fetching data:', error);
      } else {
        setData(data);
      }
    };

    fetchData();
  }, []);

  return (
    <div>
      <h1>Task List</h1>
      {data && data.map((task) => (
        <div key={task.id}>{task.name}</div>  // ここも適切にデータを表示する部分を変更
      ))}
    </div>
  );
}
