// TaskCard.js: 各タスクを表示するコンポーネント
const TaskCard = ({ task }) => {
    return (
      <div className="task-card">
        <h3>{task.title}</h3>
        <p>{task.due_date}</p>
        <p>{task.status}</p>
        <button className="edit-btn">編集</button>
        <button className="delete-btn">削除</button>
      </div>
    );
  };
  
  export default TaskCard;
  